css:
.gr-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #03050c; }
.gr-stage canvas { touch-action: none; cursor: grab; }
.gr-stage canvas.holding { cursor: grabbing; }
.gr-out { margin: 0; font-size: 22px; line-height: 1.55; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 12px 16px; min-height: 5em; }
.gr-facts { display: grid; grid-template-columns: auto 1fr; gap: 8px 14px; margin: 0; font-size: 22px; line-height: 1.5; }
.gr-facts dt { font-weight: 800; color: var(--accent); white-space: nowrap; }
.gr-facts dd { margin: 0; }
section.ex.u-done .gr-facts { display: none; }

